 function mapLayers(){if(layer)layer.remove();if(KelpPortal.combined&&window.KelpMixed){KelpMixed.redraw();return;}if(!spatial)return;layer=L.layerGroup();if($('gridLayer').checked){const max=Math.max(...Object.values(spatial.records).map(r=>median(r.series.erosion)));L.geoJSON(spatial.grids,{pane:'kelpGrid',renderer:L.svg({pane:'kelpGrid'}),style:f=>{const z=median(spatial.records[f.properties.grid_2km_id].series.erosion)/max;return {color:'#756b59',weight:1,fillColor:z>.6?'#9c6c3b':z>.25?'#c5a271':'#e4d7bc',fillOpacity:.65};},onEachFeature:(f,l)=>{l.bindTooltip(f.properties.grid_2km_id);l.on('click',()=>openArea(f.properties.grid_2km_id));}}).addTo(layer);}if($('moeLayer').checked)L.geoJSON(spatial.coverage,{pane:'kelpHabitat',renderer:L.svg({pane:'kelpHabitat'}),style:{color:'#435e32',weight:2,opacity:1,fillColor:'#c0c583',fillOpacity:.68},onEachFeature:(f,l)=>{const id=String(f.properties.polygon_id),r=spatial.polygons[id];l.bindTooltip('MOE '+id+' · '+fmt(r.areaM2/1e6)+' km²');l.on('mouseover',()=>l.setStyle({weight:3,fillOpacity:.85}));l.on('mouseout',()=>l.setStyle({weight:2,fillOpacity:.68}));l.on('click',()=>openArea('polygon:'+id));}}).addTo(layer);layer.addTo(KelpPortal.map);}
